    <style>
        :root{--ink:#15181d;--soft:#585f6b;--paper:#fff;--paper-soft:#f6f5f1;--line:#e4e1d9;--forest:#1e4a3d;--forest-dark:#123329;--forest-tint:#e5ece8;--gold:#a9781f;--gold-tint:#f1e7d2;--clay:#9c4b34;--clay-tint:#f1e1da;--slate:#3e4f63;--slate-tint:#e4e8ed;--radius:8px;--radius-m:14px}
        *{box-sizing:border-box} body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,system-ui,sans-serif;-webkit-font-smoothing:antialiased} body[data-shop-mode=dark]{--ink:#f4f5f2;--soft:#b9c0c5;--paper:#1d2329;--paper-soft:#151a1f;--line:#3a4249;--forest:#2f6656;--forest-dark:#1e4a3d;--forest-tint:#25443b;--gold-tint:#493c24;--clay-tint:#4a302a;--slate-tint:#303b47} h1,h2,h3,.serif{font-family:Fraunces,Georgia,serif} a{color:inherit;text-decoration:none} button,input,select,textarea{font:inherit}
        .shop-header{position:sticky;top:0;z-index:50;background:var(--paper);border-bottom:1px solid var(--line)}.shop-header__inner{max-width:1280px;margin:auto;padding:18px 48px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{min-width:0;display:flex;align-items:center;gap:11px}.brand__mark{width:32px;height:32px;flex:none}.brand__copy{min-width:0;display:flex;flex-direction:column;line-height:1.15}.brand__eyebrow{color:var(--soft);font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}.brand__name{margin-top:1px;font-family:Fraunces,Georgia,serif;font-size:18px;font-weight:560;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:min(42vw,320px)}.nav{display:flex;gap:30px}.nav a{padding:6px 0;border-bottom:1.5px solid transparent;color:var(--soft);font-size:14px}.nav a:hover,.nav a.active{color:var(--ink);border-color:var(--forest)}.actions{display:flex;align-items:center;gap:6px}.icon{position:relative;width:38px;height:38px;border:0;border-radius:50%;background:transparent;color:var(--ink);display:inline-grid;place-items:center;cursor:pointer}.icon:hover{background:var(--paper-soft)}.cart-count{position:absolute;top:2px;right:2px;min-width:15px;height:15px;border-radius:99px;background:var(--forest);color:#fff;display:grid;place-items:center;font-size:9.5px;font-weight:800}.shop-button{min-height:36px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--ink);padding:8px 13px;font-size:13px;font-weight:700;cursor:pointer}.shop-button--solid{border-color:var(--forest);background:var(--forest);color:#fff}.shop-button--solid:hover{background:var(--forest-dark)}.customer-name{max-width:145px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--soft);font-size:13px}.theme-sun{display:none}body[data-shop-mode=dark] .theme-sun{display:block}body[data-shop-mode=dark] .theme-moon{display:none}
        .page{min-height:calc(100vh - 75px)}.notice{max-width:1180px;margin:18px auto 0;padding:12px 16px;border-radius:var(--radius);font-size:13px}.notice--ok{background:var(--forest-tint);color:var(--forest-dark)}.notice--error{background:var(--clay-tint);color:#74351f}.footer{margin-top:35px;border-top:1px solid var(--line);background:var(--paper-soft)}.footer__inner{max-width:1280px;margin:auto;padding:48px;display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:40px}.footer__name{font-family:Fraunces,Georgia,serif;font-size:19px}.footer p,.footer a{color:var(--soft);font-size:13px;line-height:1.6}.footer a{display:block;width:max-content;padding:4px 0}.footer h2{margin:0 0 10px;font-family:Inter,sans-serif;font-size:12px;letter-spacing:.05em;text-transform:uppercase;color:var(--soft)}.footer__bottom{border-top:1px solid var(--line);padding:18px;text-align:center;color:var(--soft);font-size:12px}
        .shop-page{max-width:1180px;margin:auto;padding:40px 48px 64px}.page-header{margin-bottom:32px;padding:32px;border-radius:var(--radius-m);background:var(--forest);color:#fff;display:flex;align-items:end;justify-content:space-between;gap:24px}.eyebrow{color:#b9d0c4;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase}.page-header h1{margin:8px 0 0;font-size:32px;font-weight:560}.page-header p{margin:9px 0 0;color:#d3e0da;font-size:14px;line-height:1.55}.surface,.summary{border:1px solid var(--line);border-radius:var(--radius);background:var(--paper);padding:22px}.summary{background:var(--paper-soft)}.surface h2,.summary h2{margin:0;font-size:21px;font-weight:560}.action{min-height:40px;border:0;border-radius:6px;background:var(--ink);color:#fff;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;padding:9px 15px;font-size:13px;font-weight:700}.action:hover{background:var(--forest-dark)}.action--soft{border:1px solid var(--line);background:var(--paper);color:var(--ink)}.action--soft:hover{border-color:var(--forest);background:var(--forest-tint);color:var(--forest-dark)}.action--danger{background:transparent;color:var(--clay);padding:0}.action--danger:hover{background:transparent;text-decoration:underline}.note{margin-top:8px;color:var(--soft);font-size:12px;line-height:1.45}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-top:24px}.field--full{grid-column:1 / -1}.field label{display:block;margin-bottom:7px;font-size:13px;font-weight:700}.input{width:100%;min-height:42px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--ink);padding:9px 11px}.input:focus{outline:0;border-color:var(--forest);box-shadow:0 0 0 3px rgba(30,74,61,.12)}.totals{margin-top:18px;display:grid;gap:11px}.total{display:flex;justify-content:space-between;gap:16px;color:var(--soft);font-size:14px}.total strong{color:var(--ink)}.total--final{margin-top:6px;padding-top:16px;border-top:1px solid var(--line);color:var(--ink);font-family:Fraunces,Georgia,serif;font-size:20px}.total--final strong{color:var(--forest-dark)}.line-item{padding:18px 0;border-bottom:1px solid var(--line);display:grid;grid-template-columns:minmax(0,1fr) auto;gap:18px}.line-item:last-child{border:0;padding-bottom:0}.line-name{font-size:14px;font-weight:700}.line-meta{margin-top:5px;color:var(--soft);font-size:12.5px;line-height:1.5}.line-price{font-family:Fraunces,Georgia,serif;font-size:17px;white-space:nowrap}.quantity{width:68px;min-height:38px;border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--ink);text-align:center}.item-actions{display:flex;align-items:center;gap:10px;margin-top:12px}.status{width:max-content;border-radius:99px;padding:4px 10px;font-size:11px;font-weight:700}.status--pending,.status--pending_pos{background:var(--gold-tint);color:#76520e}.status--processing{background:var(--slate-tint);color:var(--slate)}.status--shipped,.status--delivered{background:var(--forest-tint);color:var(--forest-dark)}.status--cancelled,.status--rejected{background:var(--clay-tint);color:#74351f}
        @media(max-width:960px){.nav{display:none}.shop-header__inner,.footer__inner{padding-left:24px;padding-right:24px}.footer__inner{grid-template-columns:1fr 1fr}}@media(max-width:640px){.shop-header__inner{padding:14px 20px;gap:12px}.brand__name{max-width:34vw}.shop-page{padding:28px 20px 44px}.page-header{align-items:flex-start;flex-direction:column;padding:25px 22px}.page-header h1{font-size:28px}.form-grid{grid-template-columns:1fr}.field--full{grid-column:auto}.line-item{grid-template-columns:1fr;gap:10px}.footer__inner{grid-template-columns:1fr;padding:40px 20px;gap:24px}}
        @stack('styles')
